def evaluate(expr):
    toks, i = [], 0
    while i < len(expr):
        c = expr[i]
        if c.isspace(): i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'): j += 1
            try: toks.append(float(expr[i:j]))
            except ValueError: raise ValueError('number')
            i = j
        elif c in '+-*/^()': toks.append(c); i += 1
        else: raise ValueError('char')
    pos = [0]
    def peek(): return toks[pos[0]] if pos[0] < len(toks) else None
    def nxt(): v = peek(); pos[0] += 1; return v
    def expr_():
        v = term()
        while peek() in ('+', '-'):
            op = nxt(); r = term(); v = v + r if op == '+' else v - r
        return v
    def term():
        v = unary()
        while peek() in ('*', '/'):
            op = nxt(); r = unary(); v = v * r if op == '*' else v / r
        return v
    def unary():
        if peek() == '-': nxt(); return -unary()
        return power()
    def power():
        b = atom()
        if peek() == '^': nxt(); return b ** unary()
        return b
    def atom():
        t = nxt()
        if isinstance(t, float): return t
        if t == '(':
            v = expr_()
            if nxt() != ')': raise ValueError('paren')
            return v
        raise ValueError('atom')
    v = expr_()
    if pos[0] != len(toks): raise ValueError('trailing')
    return v

def parse_csv_line(line):
    out, i, n = [], 0, len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1; buf = []
            while True:
                if i >= n: raise ValueError('unterminated')
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"': buf.append('"'); i += 2; continue
                    i += 1; break
                buf.append(line[i]); i += 1
            out.append(''.join(buf))
        else:
            j = line.find(',', i)
            j = n if j < 0 else j
            out.append(line[i:j]); i = j
        if i >= n: return out
        if line[i] != ',': raise ValueError('junk')
        i += 1
        if i >= n: out.append(''); return out

import heapq
def shortest_path(graph, start, end):
    dist, prev, heap = {start: 0}, {}, [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist.get(u, float('inf')): continue
        for v, w in graph.get(u, {}).items():
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd; prev[v] = u; heapq.heappush(heap, (nd, v))
    if end not in dist: return (float('inf'), [])
    path = [end]
    while path[-1] != start: path.append(prev[path[-1]])
    return (dist[end], path[::-1])

def is_match(s, p):
    from functools import lru_cache
    @lru_cache(None)
    def m(i, j):
        if j == len(p): return i == len(s)
        first = i < len(s) and p[j] in (s[i], '.')
        if j + 1 < len(p) and p[j+1] == '*':
            return m(i, j+2) or (first and m(i+1, j))
        return first and m(i+1, j+1)
    return m(0, 0)

