import re
def flatten(obj):
    out = {}
    def rec(v, p):
        if isinstance(v, dict) and v:
            for k, x in v.items(): rec(x, f"{p}.{k}" if p else k)
        elif isinstance(v, list) and v:
            for i, x in enumerate(v): rec(x, f"{p}[{i}]")
        else: out[p] = v
    if not obj: return {}
    rec(obj, '')
    return out
class _N(dict): pass
def unflatten(d):
    root = _N()
    for key, val in d.items():
        toks = re.findall(r'[^.\[\]]+|\[\d+\]', key)
        cur = root
        for k, t in enumerate(toks):
            idx = int(t[1:-1]) if t.startswith('[') else t
            if k == len(toks) - 1: cur[idx] = val
            else:
                cur = cur.setdefault(idx, _N())
    def conv(x):
        if isinstance(x, _N):
            x = {k: conv(v) for k, v in x.items()}
            if x and all(isinstance(k, int) for k in x): return [x[i] for i in sorted(x)]
            return x
        return x
    return conv(root)

class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls; self.period = period; self.calls = []
    def allow(self, now):
        self.calls = [t for t in self.calls if now - t < self.period]
        if len(self.calls) < self.max_calls:
            self.calls.append(now); return True
        return False

