import random, itertools
def brute(jobs):
    best=0
    for r in range(len(jobs)+1):
        for comb in itertools.combinations(jobs,r):
            cs=sorted(comb,key=lambda j:j[0])
            if all(cs[i][1]<=cs[i+1][0] for i in range(len(cs)-1)):
                best=max(best,sum(j[2] for j in cs))
    return best
