_DEL = object()
class TxStore:
    def __init__(self): self.base = {}; self.stack = []
    def set(self, k, v): (self.stack[-1] if self.stack else self.base)[k] = v
    def delete(self, k):
        if self.stack: self.stack[-1][k] = _DEL
        else: self.base.pop(k, None)
    def get(self, k):
        for layer in reversed(self.stack):
            if k in layer: return None if layer[k] is _DEL else layer[k]
        return self.base.get(k)
    def begin(self): self.stack.append({})
    def rollback(self):
        if not self.stack: raise RuntimeError('no tx')
        self.stack.pop()
    def commit(self):
        if not self.stack: raise RuntimeError('no tx')
        top = self.stack.pop()
        if self.stack: self.stack[-1].update(top)
        else:
            for k, v in top.items():
                if v is _DEL: self.base.pop(k, None)
                else: self.base[k] = v
